#pragma once
#include <functional>

#include "Edge.hpp"
#include "PathVertex.hpp"


namespace generator {


/// Path generated by evaluating callback functions at even intervals.
class ParametricPath {
public:

	class EdgeGenerator {
	public:

		Edge Generate() const;
		bool Done() const noexcept;
		void Next();

	private:

		EdgeGenerator(const ParametricPath& path);

		const ParametricPath* m_path;

		int m_i;


	friend class ParametricPath;
	};

	class VertexGenerator {
	public:

		PathVertex Generate() const;
		bool Done() const noexcept;
		void Next();

	private:

		VertexGenerator(const ParametricPath& path);

		const ParametricPath* m_path;

		int m_i;

	friend class ParametricPath;
	};


	/// @param eval A callback that should return a PathVertex for a given value.
	/// @param segments The number of segments along the path.
	/// Should be >= 1.f Zero yields an empry path.
	explicit ParametricPath(
		std::function<PathVertex(float)> eval,
		int segments = 16
	) noexcept;

	EdgeGenerator Edges() const noexcept;

	VertexGenerator Vertices() const noexcept;

private:

	std::function<PathVertex(float)> m_eval;

	int m_segments;

	float m_delta;

};


}

